import { uploadUnassignedDocument, uploadCompanyDocument, assignStagedDocument } from '@/lib/privateDocuments';
import { useState, useRef, useCallback } from 'react';
import { useOutletContext } from 'react-router-dom';
import { base44 } from '@/api/base44Client';
import { Upload, CloudUpload, Zap, CheckCircle2, AlertTriangle } from 'lucide-react';
import PageHeader from '@/components/ui/PageHeader';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import ColaProcesamiento from '@/components/modelos/ColaProcesamiento';
import PanelRevision from '@/components/modelos/PanelRevision';
import { generarEmailPremium } from '@/lib/emailPremium';
import { generarMensajeWhatsApp, formatearTelefono } from '@/lib/whatsappMensaje';

let nextId = 1;


const MODELO_A_CARPETA = {
  modelo_303: 'fiscal_iva', modelo_390: 'fiscal_iva',
  modelo_130: 'fiscal_irpf', modelo_111: 'fiscal_retenciones', modelo_115: 'fiscal_retenciones',
  modelo_202: 'fiscal_is', modelo_200: 'fiscal_is',
  modelo_349: 'fiscal_intracomunitarias',
  modelo_420_igic: 'fiscal_igic', modelo_425_igic: 'fiscal_igic',
  renta: 'fiscal_irpf', cuentas_anuales: 'cont_cuentas_anuales',
  otra: 'fiscal_declaraciones',
};

async function extraerConIA(fileUrl, fileName) {
  // Lee el PDF completo y extrae datos del documento real
  const result = await base44.controlledCore.InvokeLLM({
    prompt: `Eres un experto en modelos fiscales españoles. Lee este PDF y extrae TODOS los datos posibles.

Busca especialmente:
- DNI/CIF/NIF del contribuyente (en mayúsculas, formato español: 12345678A o 12345678-A)
- Razón social / Nombre completo
- Modelo fiscal (303, 390, 130, 111, 115, 202, 200, 349, 420, 425, IS, Renta, etc.)
- Ejercicio / Año (4 dígitos)
- Período (T1, T2, T3, T4, 1T, 2T, 3T, 4T, o el trimestre que aparezca)
- CSV (código de autenticación)
- NRC (número de referencia de control)
- Importe total a ingresar o devolver

Nombre archivo: "${fileName}"

Responde SIEMPRE en JSON, incluso si algunos campos están vacíos. Para confianza: usa "alta" si tienes NIF+modelo claros, "media" si modelo es claro pero faltan datos, "baja" si hay dudas o ambigüedad.`,
    file_urls: fileUrl,
    response_json_schema: {
      type: 'object',
      properties: {
        modelo: { type: 'string', description: 'Ej: modelo_303, modelo_390' },
        ejercicio: { type: 'string', description: '4 dígitos' },
        periodo: { type: 'string', description: 'T1, T2, T3, T4 o similar' },
        trimestre: { type: 'string' },
        nif_cif: { type: 'string', description: 'DNI/CIF/NIF en mayúsculas' },
        razon_social: { type: 'string' },
        importe: { type: 'number' },
        csv: { type: 'string' },
        nrc: { type: 'string' },
        confianza: { type: 'string', description: 'alta, media o baja' }
      }
    }
  });
  return result;
}

async function buscarEmpresa(companies, nif, razonSocial) {
  if (nif) {
    const match = companies.find(c => c.nif_cif?.replace(/\s/g,'').toLowerCase() === nif.replace(/\s/g,'').toLowerCase());
    if (match) return match;
  }
  if (razonSocial) {
    const lower = razonSocial.toLowerCase();
    const match = companies.find(c => c.razon_social?.toLowerCase().includes(lower) || lower.includes(c.razon_social?.toLowerCase()));
    if (match) return match;
  }
  return null;
}

export default function SubidaMasivaModelos() {
  const { user, isAdmin } = useOutletContext() || {};
  const [items, setItems] = useState([]);
  const [companies, setCompanies] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  const [dragOver, setDragOver] = useState(false);
  const [companiesLoaded, setCompaniesLoaded] = useState(false);
  const fileRef = useRef(null);

  const loadCompanies = async () => {
    if (companiesLoaded) return;
    const data = await base44.entities.Company.list();
    setCompanies(data || []);
    setCompaniesLoaded(true);
    return data || [];
  };

  const procesarItem = useCallback(async (id, file, companiesList) => {
    setItems(prev => prev.map(i => i.id === id ? { ...i, estado: 'procesando' } : i));

    // 1. Subir PDF primero
    const { file_url } = await uploadUnassignedDocument(file);

    // 2. IA lee el PDF completo
    const extraccion = await extraerConIA(file_url, file.name);

    // 3. Buscar cliente por NIF (lo más importante ahora)
    const empresa = await buscarEmpresa(companiesList, extraccion?.nif_cif, extraccion?.razon_social);

    const estado = empresa
      ? (extraccion?.confianza === 'baja' ? 'revision' : 'identificado')
      : 'no_identificado';

    const previewUrl = file.type === 'application/pdf' ? file_url : null;

    setItems(prev => prev.map(i => i.id === id ? {
      ...i, estado,
      extraccion: { ...extraccion, company_id: empresa?.id },
      previewUrl
    } : i));
  }, []);

  const handleFiles = async (files) => {
    const companiesList = await loadCompanies();
    const newItems = Array.from(files).map(f => ({
      id: nextId++, file: f, estado: 'pendiente', extraccion: null, previewUrl: null
    }));
    setItems(prev => [...prev, ...newItems]);
    if (newItems.length > 0) setSelectedId(newItems[0].id);
    // Procesar en paralelo (máx 3 a la vez)
    const chunks = [];
    for (let i = 0; i < newItems.length; i += 3) chunks.push(newItems.slice(i, i + 3));
    for (const chunk of chunks) {
      await Promise.all(chunk.map(item => procesarItem(item.id, item.file, companiesList)));
    }
  };

  const handleConfirmar = async (item, empresa) => {
    if (!empresa) return;
    const ex = item.extraccion || {};
    const now = new Date();
    const nombreArchivo = `${empresa.razon_social?.replace(/\s+/g,'_')}_${empresa.nif_cif}_${ex.modelo || 'doc'}_${ex.ejercicio || ''}_${ex.periodo || ''}.pdf`;
    const carpeta = MODELO_A_CARPETA[ex.modelo] || 'fiscal_declaraciones';
    const modeloLabel = (ex.modelo || 'Modelo fiscal').replace(/_/g, ' ').toUpperCase();
    const periodo = ex.periodo || ex.trimestre || ex.ejercicio || '';
    const emailEmpresa = empresa.email || empresa.owner_email;

    // Asegura una URL de archivo válida: si el PDF no se subió durante el procesamiento, se sube ahora
    let archivoUrl = typeof item.previewUrl === 'string' && item.previewUrl.trim() !== '' ? item.previewUrl : '';
    if (!archivoUrl && item.file) {
      const { file_url } = await uploadCompanyDocument({ file: item.file, companyId: empresa.id });
      archivoUrl = file_url;
      setItems(prev => prev.map(i => i.id === item.id ? { ...i, previewUrl: archivoUrl } : i));
    }
    if (!archivoUrl) {
      setItems(prev => prev.map(i => i.id === item.id ? { ...i, estado: 'ignorado' } : i));
      return;
    }

    // Copy a verified admin-staging asset to the confirmed company. Preserve the
    // original in staging until archival completes; never infer ownership in AI.
    archivoUrl = (await assignStagedDocument(archivoUrl, empresa.id)).file_url;
    // 1. Archivar PDF en Documentos
    const docData = {
      company_id: empresa.id,
      nombre: nombreArchivo,
      carpeta,
      archivo_url: archivoUrl,
      tipo_archivo: 'application/pdf',
      anio: parseInt(ex.ejercicio) || now.getFullYear(),
      trimestre: ex.trimestre,
      estado: 'aprobado',
      etiquetas: [ex.modelo, 'presentado', 'taxea'].filter(Boolean),
      subido_por: user?.email,
      fiscal_model_code: String(ex.modelo || '').replace(/^modelo_/, '').replace(/_igic$/, '').replace(/\D/g, ''),
      fiscal_period: periodo,
      fiscal_year: parseInt(ex.ejercicio) || now.getFullYear(),
      fiscal_document_kind: 'justificante_presentacion',
      administracion: carpeta === 'fiscal_modelos_atc' ? 'ATC' : 'AEAT',
      fiscal_link_status: 'detectado',
    };
    const doc = await base44.entities.Document.create(docData);

    // 2. Vincular con el calendario fiscal y actualizar la obligación sin inventar el vencimiento
    let oblig = null;
    if (ex.modelo && periodo) {
      const linkResponse = await base44.functions.invoke('fiscalCalendarOperations', {
        action: 'link_document',
        companyId: empresa.id,
        documentId: doc.id,
        modelCode: String(ex.modelo).replace(/^modelo_/, '').replace(/_igic$/, '').replace(/\D/g, ''),
        period: periodo,
        year: parseInt(ex.ejercicio) || now.getFullYear(),
        documentKind: 'justificante_presentacion',
      });
      oblig = linkResponse.data?.obligation || null;
      if (oblig) {
        oblig = await base44.entities.TaxObligation.update(oblig.id, {
          estado: 'presentado',
          justificante_url: doc.archivo_url,
          comentarios_asesor: [
            oblig.comentarios_asesor || '',
            `Presentado por Taxea el ${now.toLocaleDateString('es-ES')}`,
            ex.csv ? `CSV: ${ex.csv}` : '',
            ex.nrc ? `NRC: ${ex.nrc}` : ''
          ].filter(Boolean).join(' | '),
          importe: ex.importe || oblig.importe,
        });
      }
    }

    // 3. Notificación interna
    await base44.entities.Notification.create({
      company_id: empresa.id,
      destinatario_email: emailEmpresa,
      titulo: `✅ ${modeloLabel} presentado`,
      mensaje: `Taxea ha presentado recientemente tu ${modeloLabel} ${periodo}. Tu documentación fiscal está al día.`,
      tipo: 'documento_revisado',
      leida: false,
      url_referencia: '/obligaciones',
    });

    // 4. Email premium HTML
    if (emailEmpresa) {
      const htmlEmail = generarEmailPremium({
        modeloKey: ex.modelo,
        ejercicio: ex.ejercicio,
        periodo,
        importe: ex.importe,
        csv: ex.csv,
        nrc: ex.nrc,
        fechaPresentacion: now.toISOString(),
        razonSocial: empresa.razon_social || empresa.nombre_comercial,
        resultado: ex.resultado,
      });
      await base44.controlledCore.SendEmail({
        operation: 'tax_notice', companyId: empresa.id, documentId: doc.id,
        subject: `Tu ${modeloLabel} ha sido presentado correctamente — Taxea Strategies`,
        body: htmlEmail,
      });
    }

    // 5. WhatsApp: conservar borrador sin enviar; el canal automático no está contratado.
    const telefonoRaw = empresa.telefono;
    const telefonoFormateado = formatearTelefono(telefonoRaw);

    if (telefonoFormateado) {
      const mensajeWA = generarMensajeWhatsApp({
        nombreCliente: empresa.razon_social || empresa.nombre_comercial,
        modeloKey: ex.modelo,
        ejercicio: ex.ejercicio,
        periodo,
        importe: ex.importe,
        csv: ex.csv,
        nrc: ex.nrc,
        resultado: ex.resultado,
      });

      // Crear log primero
      await base44.entities.WhatsAppLog.create({
        company_id: empresa.id,
        destinatario_nombre: empresa.razon_social || empresa.nombre_comercial,
        destinatario_telefono: telefonoFormateado,
        modelo_label: modeloLabel,
        periodo,
        mensaje: mensajeWA,
        estado: 'pendiente',
        proveedor: 'manual',
        error_detalle: 'Borrador. Envío automático por WhatsApp desactivado.',
        obligacion_id: oblig?.id,
      });

      // El mensaje queda disponible para revisión manual; no se llama a un proveedor externo.
    }

    // 6. Timeline
    await base44.entities.TimelineEvent.create({
      company_id: empresa.id,
      tipo: 'modelo_presentado',
      titulo: `${modeloLabel} presentado`,
      descripcion: `Presentado por Taxea el ${now.toLocaleDateString('es-ES')}${periodo ? ` — Período: ${periodo}` : ''}${ex.csv ? ` — CSV: ${ex.csv}` : ''}`,
      color: 'verde',
      entidad_tipo: 'TaxObligation',
      entidad_id: oblig?.id,
      usuario_email: user?.email,
      automatico: false,
      visibilidad: 'ambos',
      afecta_health_score: true,
      estado_nuevo: 'presentado',
    });

    // 6. Actualizar health score del cliente
    const crm = await base44.entities.ClientCRM.filter({ company_id: empresa.id });
    if (crm[0]) {
      const newScore = Math.min(100, (crm[0].health_score || 75) + 5);
      await base44.entities.ClientCRM.update(crm[0].id, {
        health_score: newScore,
        estado_fiscal: 'verde',
      });
    }

    // 7. Marcar como confirmado
    setItems(prev => prev.map(i => i.id === item.id ? { ...i, estado: 'confirmado' } : i));
  };

  const handleIgnorar = (id) => {
    setItems(prev => prev.map(i => i.id === id ? { ...i, estado: 'ignorado' } : i));
  };

  const handleReprocesar = async (id) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    const companiesList = companiesLoaded ? companies : await loadCompanies();
    await procesarItem(id, item.file, companiesList);
  };

  const confirmarTodosIdentificados = async () => {
    const pendientes = items.filter(i => i.estado === 'identificado');
    for (const item of pendientes) {
      const empresa = companies.find(c => c.id === item.extraccion?.company_id);
      if (empresa) await handleConfirmar(item, empresa);
    }
  };

  const selectedItem = items.find(i => i.id === selectedId);
  const hayIdentificados = items.some(i => i.estado === 'identificado');

  if (!isAdmin) return (
    <div className="flex items-center justify-center h-64 text-center">
      <div>
        <p className="text-sm font-medium text-foreground">Acceso restringido</p>
        <p className="text-xs text-muted-foreground mt-1">Solo administradores pueden usar esta herramienta</p>
      </div>
    </div>
  );

  return (
    <div>
      <PageHeader title="Subida masiva de modelos" subtitle="Sube PDFs · IA identifica cliente y archiva automáticamente">
        {hayIdentificados && (
          <Button onClick={confirmarTodosIdentificados} className="bg-teal hover:bg-teal-dark h-9">
            <Zap className="w-4 h-4 mr-1.5" /> Confirmar todos ({items.filter(i => i.estado === 'identificado').length})
          </Button>
        )}
      </PageHeader>

      {items.length === 0 ? (
        /* Drop zone inicial */
        <div
          onDragOver={e => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onDrop={e => { e.preventDefault(); setDragOver(false); handleFiles(e.dataTransfer.files); }}
          onClick={() => fileRef.current?.click()}
          className={cn('border-2 border-dashed rounded-2xl p-16 text-center cursor-pointer transition-all',
            dragOver ? 'border-teal bg-teal/5' : 'border-border hover:border-teal/40 hover:bg-secondary/20')}
        >
          <div className="w-16 h-16 bg-teal-light rounded-2xl mx-auto mb-4 flex items-center justify-center">
            <CloudUpload className="w-8 h-8 text-teal" />
          </div>
          <p className="text-lg font-semibold text-foreground mb-1">Arrastra los PDFs aquí</p>
          <p className="text-sm text-muted-foreground mb-4">Modelos 303, 390, 130, 111, 115, 200, 202, 349, 420, 425, Rentas, IS…</p>
          <Button variant="outline" className="mx-auto">
            <Upload className="w-4 h-4 mr-2" /> Seleccionar archivos
          </Button>
          <input ref={fileRef} type="file" multiple accept=".pdf" className="hidden"
            onChange={e => handleFiles(e.target.files)} />
        </div>
      ) : (
        <div className="flex gap-4 h-[calc(100vh-220px)] min-h-96">
          {/* Cola izquierda */}
          <div className="w-72 flex-shrink-0 bg-card border border-border rounded-xl shadow-card overflow-hidden flex flex-col">
            <div className="flex items-center justify-between px-3 py-2.5 border-b border-border">
              <p className="text-xs font-semibold text-foreground">Cola de procesamiento</p>
              <button onClick={() => fileRef.current?.click()}
                className="text-xs text-teal hover:underline flex items-center gap-1">
                <Upload className="w-3 h-3" /> Añadir más
              </button>
            </div>
            <div className="flex-1 overflow-hidden">
              <ColaProcesamiento items={items} selectedId={selectedId} onSelect={setSelectedId} onReprocesar={handleReprocesar} />
            </div>
            <input ref={fileRef} type="file" multiple accept=".pdf" className="hidden"
              onChange={e => handleFiles(e.target.files)} />
          </div>

          {/* Panel revisión derecha */}
          <div className="flex-1 bg-card border border-border rounded-xl shadow-card overflow-hidden flex flex-col">
            <div className="flex items-center justify-between px-4 py-2.5 border-b border-border">
              <p className="text-xs font-semibold text-foreground">Panel de revisión</p>
              {selectedItem && (
                <div className="flex items-center gap-2">
                  {selectedItem.estado === 'confirmado' && (
                    <span className="flex items-center gap-1 text-xs text-green-600">
                      <CheckCircle2 className="w-3.5 h-3.5" /> Archivado
                    </span>
                  )}
                  {['revision','no_identificado'].includes(selectedItem.estado) && (
                    <span className="flex items-center gap-1 text-xs text-amber-600">
                      <AlertTriangle className="w-3.5 h-3.5" /> Requiere revisión manual
                    </span>
                  )}
                </div>
              )}
            </div>
            <div className="flex-1 overflow-hidden">
              <PanelRevision
                item={selectedItem}
                companies={companies}
                onConfirmar={handleConfirmar}
                onIgnorar={handleIgnorar}
                onReprocesar={handleReprocesar}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

base44/functions/documentStorage/entry.t:
import { createClientFromRequest } from 'npm:@base44/sdk@0.8.48';
import { storageConfiguration, publicStorageCertificate, STORAGE_BUCKET, STORAGE_ACCOUNT } from './storageCredentials.mjs';
import { verifyStorageConnection, boundedBytes } from './storageTransport.mjs';
import { storageCompany, isStorageAdmin, savePrivateAsset, resolvePrivateAsset, storageEnabled, authorizedAsset, readPrivateAssetBytes, assetReference } from './storageAssets.mjs';
import { verifySignedStorageConnection } from './storageSigning.mjs';

const disabled=(user:any)=>[user,user?.data].filter(Boolean).some(state=>state.is_deleted===true
 ||['eliminado','bloqueado','suspendido'].includes(String(state.status||'').trim().toLowerCase())
 ||['disabled','deleted','blocked','suspended'].includes(String(state.accountAccessStatus||'').trim().toLowerCase()));
const response=(data:any,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'}});

Deno.serve(async req=>{
 let admin=false;
 try {
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  const client=createClientFromRequest(req);
  const user=await client.auth.me().catch(()=>null);
  if(!user?.id)return response({error:'Inicia sesión.'},401);
  if(disabled(user))return response({error:'Acceso al portal suspendido.'},403);
  admin=isStorageAdmin(user);
  const multipart=(req.headers.get('content-type')||'').includes('multipart/form-data');
  let body:any;
  try{
   const bytes=await boundedBytes(req,multipart?25*1024*1024+32768:16384);
   body=multipart?Object.fromEntries((await new Response(bytes,{headers:{'content-type':req.headers.get('content-type')}}).formData()).entries()):JSON.parse(new TextDecoder().decode(bytes));
  }catch{return response({error:'Solicitud no válida o demasiado grande.'},400);}
  const action=body?.action;
  if(['public_certificate','verify_connection','verify_signed_connection'].includes(action)){
   if(!admin)return response({error:'Acceso reservado a administración.'},403);
   if(action==='verify_connection')return response({ok:true,...await verifyStorageConnection(Deno.env)});
   if(action==='verify_signed_connection')return response({ok:true,...await verifySignedStorageConnection(Deno.env)});
   const config=storageConfiguration(Deno.env),certificate=await publicStorageCertificate(config);
   return response({ok:true,...certificate,account:STORAGE_ACCOUNT,bucket:STORAGE_BUCKET,privateKeyExposed:false});
  }
  if(['staging_capabilities','upload_staging','assign_staged_asset'].includes(action)){
   if(!admin)return response({error:'Acceso reservado a administración.'},403);
   if(action==='staging_capabilities')return response({ok:true,privateStorageEnabled:Deno.env.get('TAXEA_PRIVATE_STORAGE_ENFORCED')==='true'||Deno.env.get('TAXEA_PRIVATE_DMS_ENFORCED')==='true'});
   if(action==='upload_staging'){
    if(!multipart||!(body.file instanceof File))return response({error:'Archivo no válido.'},400);
    const staged=await savePrivateAsset(client.asServiceRole,user,{id:'__admin_staging__',activa:true,private_document_storage_enabled:true},body.file,Deno.env);
    return response({ok:true,file_url:staged.file_url,assetId:staged.asset.id,reused:staged.reused});
   }
   const source=await authorizedAsset(client.asServiceRole,user,body.assetId);
   const target=await storageCompany(client.asServiceRole,user,body.companyId);
   if(!source||source.company_id!=='__admin_staging__'||!target)return response({error:'Documento o empresa no disponibles.'},404);
   const {bytes}=await readPrivateAssetBytes(client.asServiceRole,user,assetReference(source.id),Deno.env);
   const file=new File([bytes],source.original_name,{type:source.mime_type});
   const saved=await savePrivateAsset(client.asServiceRole,user,{...target,private_document_storage_enabled:true},file,Deno.env);
   return response({ok:true,file_url:saved.file_url,assetId:saved.asset.id,reused:saved.reused});
  }
  if(!['capabilities','upload','resolve','download'].includes(action))return response({error:'Operación no admitida.'},400);
  const svc=client.asServiceRole;
  if(['resolve','download'].includes(action)){
   const asset=await authorizedAsset(svc,user,body.assetId);
   if(!asset)return response({error:'Documento no disponible.'},404);
   if(action==='resolve')return response({ok:true,mimeType:asset.mime_type,name:asset.original_name,size:asset.size,sha256:asset.sha256});
   const {bytes}=await readPrivateAssetBytes(svc,user,assetReference(asset.id),Deno.env);
   return new Response(bytes,{status:200,headers:{'Content-Type':asset.mime_type,'Content-Length':String(bytes.length),'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Cross-Origin-Resource-Policy':'same-origin','X-Taxea-File-Sha256':asset.sha256,'X-Taxea-File-Size':String(bytes.length),'X-Taxea-File-Name':encodeURIComponent(asset.original_name),'Access-Control-Expose-Headers':'X-Taxea-File-Sha256,X-Taxea-File-Size,X-Taxea-File-Name,Content-Type'}});
  }
  const company=await storageCompany(svc,user,body.companyId);
  if(!company)return response({error:'Empresa no disponible.'},403);
  const dmsEnabled=storageEnabled(company,Deno.env)||Deno.env.get('TAXEA_PRIVATE_DMS_ENFORCED')==='true';
  if(action==='capabilities')return response({ok:true,privateStorageEnabled:dmsEnabled,dmsEnforced:Deno.env.get('TAXEA_PRIVATE_DMS_ENFORCED')==='true',maxFileBytes:25*1024*1024});
  if(!multipart||!(body.file instanceof File))return response({error:'Archivo no válido.'},400);
  if(!dmsEnabled)return response({error:'El almacenamiento privado aún no está activado para esta empresa.'},409);
  const saved=await savePrivateAsset(svc,user,{...company,private_document_storage_enabled:true},body.file,Deno.env);
  return response({ok:true,file_url:saved.file_url,assetId:saved.asset.id,reused:saved.reused,sha256:saved.asset.sha256,size:saved.asset.size});
 }catch(error){
  const detail=String(error?.message||'');
  const safeCode=/^(STORAGE_AUTH_(NETWORK_(BINDING|TLS|DNS|TIMEOUT|BODY|CONNECT|TypeError|AbortError|OperationError|InvalidAccessError|ReferenceError|Error)|NOT_JSON_\d{3}|FAILED_\d{3}_(INVALID_GRANT|INVALID_CLIENT|INVALID_REQUEST|INVALID_SCOPE|UNAUTHORIZED_CLIENT|ACCESS_DENIED|UNEXPECTED))|STORAGE_STEP_AUTH_(TypeError|AbortError|OperationError|InvalidAccessError|ReferenceError|Error)|STORAGE_STEP_(AUTH|UPLOAD|READ|UNSIGNED|CLEANUP)|STORAGE_(AUTH|UPLOAD|DOWNLOAD)_FAILED_\d{3}|STORAGE_(PROBE|CLEANUP)_FAILED|PRIVATE_STORAGE_(NOT_CONFIGURED|INVALID_CONFIG)|STORAGE_(UNSUPPORTED_FILE|INVALID_SIZE|HASH_MISMATCH))$/.test(detail)?detail:'PRIVATE_STORAGE_UNAVAILABLE';
  const code=admin&&/^(QA_(ADMIN_ONLY|EXISTING_COMPANY_NOT_VERIFIED|AMBIGUOUS_COMPANY|COMPANY_NOT_VERIFIED)|STORAGE_(SIGNED_READ_FAILED_\d{3}|UPLOAD_UNVERIFIED|METADATA_HTTP_\d{3}|METADATA_UNVERIFIED|COMPANY_NOT_ENABLED))$/.test(detail)?detail:safeCode;
  const status=code==='STORAGE_UNSUPPORTED_FILE'?415:code==='STORAGE_INVALID_SIZE'?413:503;
  return response({error:'No se ha podido completar la operación de almacenamiento privado.',code,...(admin&&Array.isArray(error?.storageHints)?{diagnosticHints:error.storageHints}:{})},status);
 }
});

base44/functions/processLaborOcr/entry.t:
import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import {storageAccountEnabled,storageCompany,assetIdFromReference,authorizedAsset,resolvePrivateAsset} from './storageRuntime.generated.mjs';
const nativeAppFile=value=>{try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='base44.app'&&!u.port&&!u.username&&!u.password&&!u.hash&&u.pathname.startsWith('/api/apps/6a00fec50cc522a74ddde4b2/files/mp/');}catch{return false;}};

Deno.serve(async (req) => {
  if(req.method!=='POST')return Response.json({error:'Método no permitido.'},{status:405});
  const base44 = createClientFromRequest(req);
  const user = await base44.auth.me().catch(() => null);
  if (!user?.id) return Response.json({ error: 'Unauthorized' }, { status: 401 });
  if(!storageAccountEnabled(user))return Response.json({error:'Acceso suspendido.'},{status:403});

  const { document_id } = await req.json().catch(() => ({}));
  if (!document_id) return Response.json({ error: 'document_id required' }, { status: 400 });

  const docs = await base44.asServiceRole.entities.LaborOcrDocument.filter({ id: document_id });
  const doc = docs[0];
  if (!doc) return Response.json({ error: 'Document not found' }, { status: 404 });

  const company=await storageCompany(base44.asServiceRole,user,doc.company_id);
  if(!company)return Response.json({error:'Empresa no autorizada.'},{status:403});
  let providerFileUrl=doc.file_url;
  const assetId=assetIdFromReference(doc.file_url);
  if(assetId){
    const asset=await authorizedAsset(base44.asServiceRole,user,assetId);
    if(!asset||asset.company_id!==company.id)return Response.json({error:'Documento no disponible.'},{status:404});
    const resolved=await resolvePrivateAsset(base44.asServiceRole,user,assetId,Deno.env);
    if(!resolved)return Response.json({error:'Documento no disponible.'},{status:404});
    providerFileUrl=resolved.url;
  }else if(!nativeAppFile(doc.file_url))return Response.json({error:'Referencia de documento no válida.'},{status:400});

  try {
    await base44.asServiceRole.entities.LaborOcrDocument.update(doc.id, { ocr_status: 'procesando' });

    const prompt = `Eres un motor OCR especializado en nóminas españolas con conocimiento laboral, fiscal y contable. Tu misión es extraer datos con máxima precisión y marcar como dudoso cualquier dato que no puedas leer con claridad.

## REGLA CRÍTICA: NO INVENTAR DATOS
Si no puedes leer un campo con claridad, usa null y marca confidence_level como "no_fiable". Nunca:
- Uses el nombre de la empresa como empleado
- Uses el DNI del trabajador como CIF de empresa ni viceversa
- Confundas NAF/NUSS con DNI/NIE
- Confundas CCC con NAF
- Inventes el periodo desde la fecha de emisión o pago
- Confundas base de cotización con líquido
- Confundas total devengado con neto
- Uses identificadores fiscales como importes
- Generates asiento si las cifras no cuadran matemáticamente

## IDENTIFICADORES - VALIDACIONES ESTRICTAS

### DNI/NIE trabajador
- DNI: exactamente 8 dígitos + 1 letra (ej: 12345678Z)
- NIE: X, Y o Z + 7 dígitos + 1 letra (ej: X1234567L)
- Normalizar espacios y guiones antes de validar
- Si no cumple patrón estricto: confidence_level = "baja", marcar como dudoso
- Nunca aceptar CIF empresa (letra + 7 dígitos) como DNI trabajador
- Nunca aceptar NAF (12 dígitos) como DNI

### CIF/NIF empresa
- Formato: letra inicial (A,B,C,D,E,F,G,H,J,N,P,Q,R,S,U,V,W) + 7 dígitos + dígito/letra control
- Etiquetas cercanas: CIF, NIF empresa, N.I.F., C.I.F.
- Debe estar en el bloque EMPRESA, no en el bloque de trabajador
- Si aparece en zona incorrecta: marcar como conflicto

### NAF/NUSS (número afiliación SS)
- Normalmente 12 dígitos (puede aparecer como 28/1234567890 o agrupado)
- Etiquetas: NAF, NUSS, Nº afiliación, número seguridad social del trabajador
- No confundir con CCC empresa (también numérico)
- No confundir con DNI/NIE
- Validar que está en bloque TRABAJADOR

### CCC empresa
- Código Cuenta Cotización: número de la empresa ante la SS
- Tratar como identificador de empresa, no del trabajador
- Etiquetas: CCC, código cuenta cotización, cuenta de cotización

## ESTRUCTURA DE LA NÓMINA (zonas)
La nómina española tiene estos bloques. Asigna cada dato a su zona correcta:
- company_block: datos empresa (nombre, CIF, CCC, domicilio)
- employee_block: datos trabajador (nombre, DNI/NIE, NAF, grupo, categoría, antigüedad)
- period_block: periodo de liquidación (fechas del periodo, días trabajados)
- employment_block: datos laborales (contrato, jornada, puesto)
- earnings_table: tabla de devengos
- deductions_table: tabla de deducciones
- contribution_bases_block: bases de cotización CC, AT/EP
- tax_block: base IRPF, porcentaje IRPF
- totals_block: total devengado, total deducciones, líquido a percibir
- footer_block: firma, sello, pie

## PERIODO DE NÓMINA
Extraer el periodo de liquidación de estas fuentes (por orden de prioridad):
1. Etiqueta "Periodo de liquidación" o "Periodo"
2. Rango "del DD/MM/YYYY al DD/MM/YYYY"
3. "Nómina de [mes] [año]" o "Recibo de salarios correspondiente a [mes] [año]"
4. Mes/año indicado explícitamente
5. Días cotizados + mes visible

NO usar como periodo: fecha de pago, fecha de emisión, fecha de antigüedad, fecha de alta, fecha de contrato.
NUNCA convertir "del 01/03/2026 al 31/03/2026" en enero ni en fecha actual.

## PARSER NUMÉRICO EUROPEO
Formato español: coma decimal, punto de miles.
- "1.234,56" → 1234.56
- "1234,56" → 1234.56  
- "1 234,56" → 1234.56
- "-123,45" → -123.45
- "(123,45)" → -123.45
NUNCA interpretar DNI, NAF, CCC, porcentajes, días trabajados como importes monetarios.

## DEVENGOS
Etiquetas posibles: salario base, antigüedad, plus convenio, plus transporte, complemento, horas extra, paga extra, prorrata pagas extra, comisiones, incentivos, vacaciones, dietas, kilometraje, indemnización, retribución en especie.
Cada línea: descripcion_original, importe, tipo_salarial (salarial/no_salarial), cuenta_sugerida (640/641/629/...), confianza.

## DEDUCCIONES
Etiquetas posibles: IRPF, retención IRPF, contingencias comunes, desempleo, formación profesional, MEI, Seguridad Social trabajador, anticipo, embargo, valor productos en especie.
La SS trabajador puede estar desglosada en varias líneas (CC + desempleo + FP + MEI). Sumarlas correctamente.
NO confundir SS empresa con SS trabajador.

## VALIDACIONES MATEMÁTICAS OBLIGATORIAS
Verificar con tolerancia de 0.02€:
1. total_accruals ≈ suma(devengos)
2. total_deductions ≈ suma(deducciones)
3. net_pay ≈ total_accruals - total_deductions
4. irpf_amount ≈ irpf_base * (irpf_rate/100) si tienes ambos datos
5. employee_ss_amount ≈ suma(CC + desempleo + FP + MEI)

Si no cuadra: math_validation = false, incluir diferencia exacta en warnings.

## ASIENTO CONTABLE
SOLO generar asiento si: empleado validado, periodo validado, total devengado validado, líquido validado.
NUNCA inventar cuota SS empresa. Si no aparece explícitamente, marcar línea 642 como "pendiente_seguros_sociales".

Asiento devengo de nómina:
DEBE: 640 (sueldos/salarios = total devengado salarial)
HABER: 4751 (IRPF), 476 (SS trabajador), 465 (líquido a percibir)
Solo incluir 642 si aparece explícitamente la cuota patronal.
Para anticipos: usar 460. Para embargos: marcar cuenta configurable.

